#include "KaraokePage.h"
namespace {juce::String u(const char* s){return juce::String::fromUTF8(s);}}
KaraokePage::KaraokePage(StudioMain& main):owner(main),browser(main.engine.liveMusic){
    auto& e=owner.engine;auto* settings=owner.settings();e.liveMode=true;e.liveMusic.setSemitones(settings->getIntValue("liveTranspose",0));e.liveMusic.gain=static_cast<float>(settings->getDoubleValue("liveMusicGain",.7));e.monitor=settings->getBoolValue("liveMonitor",false);
    for(juce::Component* c:std::initializer_list<juce::Component*>{&browser,&search,&open,&back,&home,&down,&up,&reset,&advanced,&devices,&fx,&antares,&loadPlugin,&mic,&record,&softReverb,&title,&offset,&key,&status,&musicLabel,&micLabel,&reverbLabel,&delayLabel,&music,&micGain,&reverb,&delay,&keySelect,&scaleSelect,&autoKey})addAndMakeVisible(c);
    addAndMakeVisible(sidebar);sidebar.setViewedComponent(&controls,false);sidebar.setScrollBarsShown(true,false);
    for(juce::Component* c:std::initializer_list<juce::Component*>{&down,&up,&reset,&devices,&fx,&antares,&loadPlugin,&mic,&record,&softReverb,&offset,&key,&status,&musicLabel,&micLabel,&reverbLabel,&delayLabel,&music,&micGain,&reverb,&delay,&keySelect,&scaleSelect,&autoKey,&input})controls.addAndMakeVisible(c);
    input.setTextWhenNothingSelected(u("Ngõ micro"));input.onChange=[this]{owner.engine.inputChannel=input.getSelectedItemIndex();};
    title.setText(u("VOCAL STUDIO  /  HÁT VỚI YOUTUBE"),juce::dontSendNotification);title.setFont(juce::Font(22,juce::Font::bold));title.setColour(juce::Label::textColourId,juce::Colour(0xff6fe1c7));
    auto button=[](juce::TextButton& b,const char* text,std::function<void()> action){b.setButtonText(u(text));b.onClick=std::move(action);};
    button(open,"Mở / Tìm",[this]{browser.navigate(search.getText());});button(back,"←",[this]{browser.back();});button(home,"YouTube",[this]{browser.home();});search.setTextToShowWhenEmpty(u("Dán link YouTube hoặc nhập tên bài karaoke…"),juce::Colour(0xff8290a3));search.onReturnKey=[this]{browser.navigate(search.getText());};
    button(down,"−½ cung",[this]{change(-1);});button(up,"+½ cung",[this]{change(1);});button(reset,"Về tone gốc",[this]{owner.engine.liveMusic.setSemitones(0);sendKey();});down.setColour(juce::TextButton::buttonColourId,juce::Colour(0xff19564e));up.setColour(juce::TextButton::buttonColourId,juce::Colour(0xff19564e));
    button(advanced,"Studio nâng cao",[this]{leave();});button(devices,"Sound card",[this]{owner.openSoundCard();});button(fx,"Menu vang / verb / FX",[this]{owner.showVocalTools();});button(antares,"Mở Antares",[this]{owner.openAntaresEditor();});button(loadPlugin,"Chọn Antares VST3",[this]{owner.chooseAntaresPlugin();});button(mic,"Bật micro",[this]{auto& e=owner.engine;e.monitor=!e.monitor.load();});button(record,"Thu giọng",[this]{owner.record();});button(softReverb,"Vang ẩn",[this]{auto& e=owner.engine;e.reverb=.08f;e.delay=.025f;e.decaySeconds=1.2f;e.preDelayMs=25;e.damping=.7f;e.deharsh=.2f;});
    auto slider=[](juce::Slider& s,double lo,double hi,double step){s.setRange(lo,hi,step);s.setSliderStyle(juce::Slider::LinearHorizontal);s.setTextBoxStyle(juce::Slider::TextBoxRight,false,65,22);};slider(music,0,1.5,.01);music.setValue(e.liveMusic.gain.load(),juce::dontSendNotification);music.onValueChange=[this]{owner.engine.liveMusic.gain=static_cast<float>(music.getValue());};slider(micGain,-24,12,.1);micGain.setTextValueSuffix(" dB");micGain.setValue(e.inputDb.load(),juce::dontSendNotification);micGain.onValueChange=[this]{owner.engine.inputDb=static_cast<float>(micGain.getValue());};slider(reverb,0,.4,.01);reverb.onValueChange=[this]{owner.engine.reverb=static_cast<float>(reverb.getValue());};slider(delay,0,.3,.01);delay.onValueChange=[this]{owner.engine.delay=static_cast<float>(delay.getValue());};
    musicLabel.setText(u("Âm lượng nhạc"),juce::dontSendNotification);micLabel.setText(u("Gain micro"),juce::dontSendNotification);reverbLabel.setText("Reverb",juce::dontSendNotification);delayLabel.setText("Delay",juce::dontSendNotification);offset.setFont(juce::Font(36,juce::Font::bold));offset.setJustificationType(juce::Justification::centred);key.setJustificationType(juce::Justification::centred);status.setMultiLine(true);status.setReadOnly(true);status.setScrollbarsShown(true);
    autoKey.setButtonText(u("Tự dò tone → Antares"));autoKey.setToggleState(settings->getBoolValue("liveAutoKey",true),juce::dontSendNotification);autoKey.onClick=[this]{revision=~std::uint64_t(0);sendKey();};
    keySelect.addItemList({"C","C# / Db","D","D# / Eb","E","F","F# / Gb","G","G# / Ab","A","A# / Bb","B"},1);keySelect.setSelectedId(settings->getIntValue("liveManualKey",1),juce::dontSendNotification);scaleSelect.addItem("Major",1);scaleSelect.addItem("Minor",2);scaleSelect.setSelectedId(settings->getIntValue("liveManualScale",1),juce::dontSendNotification);keySelect.onChange=[this]{sendKey();};scaleSelect.onChange=[this]{sendKey();};
    browser.navigate(settings->getValue("liveURL","https://www.youtube.com/"));timerCallback();startTimerHz(10);
}
KaraokePage::~KaraokePage(){stopTimer();auto* p=owner.settings();p->setValue("liveTranspose",owner.engine.liveMusic.semitones());p->setValue("liveMusicGain",owner.engine.liveMusic.gain.load());p->setValue("liveMonitor",owner.engine.monitor.load());p->setValue("liveAutoKey",autoKey.getToggleState());p->setValue("liveManualKey",keySelect.getSelectedId());p->setValue("liveManualScale",scaleSelect.getSelectedId());if(browser.address().startsWith("https://"))p->setValue("liveURL",browser.address());}
void KaraokePage::leave(){if(owner.engine.isRecording()){owner.status(u("Dừng thu giọng trước khi chuyển Studio."));return;}browser.pause();owner.engine.liveMode=false;setVisible(false);owner.showQuickMode(false);}
void KaraokePage::change(int step){auto& m=owner.engine.liveMusic;m.setSemitones(m.semitones()+step);sendKey();timerCallback();}
void KaraokePage::sendKey(){auto& e=owner.engine;const auto source=e.liveMusic.key();const int base=autoKey.getToggleState()?(browser.advertisement()?-1:source.tonic):keySelect.getSelectedId()-1;const bool minor=autoKey.getToggleState()?source.minor:scaleSelect.getSelectedId()==2;const int note=base<0?-1:(base+e.liveMusic.semitones()+24)%12;if(note!=lastKey||minor!=lastMinor||revision!=source.revision||lastPlugin!=e.pluginInstance()){e.setLiveSongKey(note,minor);lastPlugin=e.pluginInstance();lastKey=note;lastMinor=minor;revision=source.revision;}key.setText(note<0?u("Đang nghe để dò tone…"):u("Tone đang hát: ")+juce::String(vocal::noteName(60+note))+(minor?" minor":" major"),juce::dontSendNotification);}
void KaraokePage::timerCallback(){if(!isVisible())return;auto& e=owner.engine;e.liveMode=true;const auto names=e.inputNames();if(input.getNumItems()!=names.size()||(names.size()>0&&input.getItemText(0)!=names[0])){input.clear(juce::dontSendNotification);input.addItemList(names,1);}input.setSelectedItemIndex(e.inputChannel.load(),juce::dontSendNotification);sendKey();const int n=e.liveMusic.semitones();offset.setText((n>0?"+":"")+juce::String(n)+u(" bán âm"),juce::dontSendNotification);down.setEnabled(n>-12);up.setEnabled(n<12);keySelect.setEnabled(!autoKey.getToggleState());scaleSelect.setEnabled(!autoKey.getToggleState());mic.setButtonText(e.monitor.load()?u("Micro đang bật · Tắt"):u("Bật micro để hát"));record.setButtonText(e.isRecording()?u("Dừng thu giọng"):u("Thu giọng"));reverb.setValue(e.reverb.load(),juce::dontSendNotification);delay.setValue(e.delay.load(),juce::dontSendNotification);
    juce::String info=u("Mở bài trên YouTube rồi hát. Mỗi lần bấm = 1 bán âm; tốc độ nhạc giữ nguyên.\n\n")+e.deviceSummary()+"\n\n"+e.pluginName()+"\n"+e.toneLinkStatus;
    info+="\n\n"+owner.userStatus();
    micLabel.setFont(12);micLabel.setText("Mic "+juce::String(vocal::gainToDb(e.inputPeak.load()),0)+" dBFS",juce::dontSendNotification);
    if(e.inputClipped.load())info+=u("\n\nMIC CLIP: giảm núm gain trên UPod Pro. Méo do quá tải đầu vào không thể sửa hoàn toàn bằng phần mềm.");
    if(browser.error().isNotEmpty())info+="\nYouTube: "+browser.error();if(browser.advertisement())info+=u("\nĐang phát quảng cáo · tạm chờ dò tone bài.");
    info+=u("\n\nUPod Pro: Mic with DSP OFF · Mixing OFF. Tắt Direct Out khi kiểm âm phần mềm.\n\nThu giọng lưu WAV micro gốc; mở Studio để mix và xuất file.");if(status.getText()!=info)status.setText(info,false);repaint();
}
void KaraokePage::resized(){const int w=getWidth(),h=getHeight(),x=w-310;title.setBounds(20,12,w-330,40);advanced.setBounds(w-190,18,170,30);back.setBounds(20,66,40,32);home.setBounds(68,66,90,32);search.setBounds(168,66,x-282,32);open.setBounds(x-104,66,94,32);browser.setBounds(20,110,x-30,h-130);sidebar.setBounds(x,64,300,h-80);controls.setSize(290,1040);const int sx=0;int y=0;devices.setBounds(sx,y,140,30);mic.setBounds(sx+146,y,144,30);y+=38;input.setBounds(sx,y,290,28);y+=40;offset.setBounds(sx,y,290,48);y+=58;down.setBounds(sx,y,140,52);up.setBounds(sx+150,y,140,52);y+=62;reset.setBounds(sx+50,y,190,30);y+=40;key.setBounds(sx,y,290,28);y+=35;autoKey.setBounds(sx,y,290,26);y+=31;keySelect.setBounds(sx,y,140,28);scaleSelect.setBounds(sx+150,y,140,28);y+=37;
    for(auto pair:std::initializer_list<std::pair<juce::Label*,juce::Slider*>>{{&musicLabel,&music},{&micLabel,&micGain},{&reverbLabel,&reverb},{&delayLabel,&delay}}){pair.first->setBounds(sx,y,92,27);pair.second->setBounds(sx+92,y,198,27);y+=32;}
    softReverb.setBounds(sx,y,90,30);fx.setBounds(sx+98,y,192,30);y+=39;loadPlugin.setBounds(sx,y,165,30);antares.setBounds(sx+173,y,117,30);y+=39;record.setBounds(sx,y,290,32);y+=42;status.setBounds(sx,y,290,300);}
void KaraokePage::paint(juce::Graphics& g){g.fillAll(juce::Colour(0xff10151e));g.setColour(juce::Colour(0xff222c3a));g.drawVerticalLine(getWidth()-322,64,static_cast<float>(getHeight()-20));}
